#include <bits/stdc++.h>
using namespace std;

// ---------- begin Matrix ----------

template <class T>
struct SemiRing {
    static T zero();
    static T one();
};

template <class T>
struct SquareMatrix {
    size_t n;
    vector<T> a;

    SquareMatrix() : n(0) {}
    SquareMatrix(size_t n_) : n(n_), a(n_ * n_) {}

    static SquareMatrix zero(size_t n) {
        SquareMatrix m(n);
        T z = SemiRing<T>::zero();
        std::fill(m.a.begin(), m.a.end(), z);
        return m;
    }

    static SquareMatrix identity(size_t n) {
        SquareMatrix m = zero(n);
        for (size_t i = 0; i < n; i++) {
            m.a[i * n + i] = SemiRing<T>::one();
        }
        return m;
    }

    void set_at(size_t i, size_t j, T v) {
        assert(i < n && j < n);
        a[i * n + j] = v;
    }

    T get_at(size_t i, size_t j) const {
        assert(i < n && j < n);
        return a[i * n + j];
    }

    static SquareMatrix matmul(const SquareMatrix &l, const SquareMatrix &r) {
        return l * r;
    }

    SquareMatrix operator+(const SquareMatrix &rhs) const {
        assert(n == rhs.n);
        SquareMatrix c = zero(n);
        for (size_t i = 0; i < n * n; i++) {
            c.a[i] = a[i] + rhs.a[i];
        }
        return c;
    }

    SquareMatrix operator*(const SquareMatrix &rhs) const {
        assert(n == rhs.n);
        SquareMatrix c = zero(n);
        for (size_t i = 0; i < n; i++) {
            for (size_t k = 0; k < n; k++) {
                T aval = a[i * n + k];
                for (size_t j = 0; j < n; j++) {
                    c.a[i * n + j] = c.a[i * n + j] + aval * rhs.a[k * n + j];
                }
            }
        }
        return c;
    }
};

// ---------- end Matrix ----------
// ---------- begin ModInt ----------

const uint32_t MOD = 1000000000 + 7;
using Num = uint32_t;

struct ModInt {
    Num v;
    ModInt() : v(0) {}
    ModInt(Num _v) : v(_v % MOD) {}
};

ModInt operator+(ModInt a, ModInt b) {
    uint32_t d = a.v + b.v;
    if (d >= MOD) d -= MOD;
    return ModInt(d);
}

ModInt& operator+=(ModInt &a, ModInt b) {
    a = a + b;
    return a;
}

ModInt operator-(ModInt a, ModInt b) {
    uint32_t d = a.v + MOD - b.v;
    if (d >= MOD) d -= MOD;
    return ModInt(d);
}

ModInt& operator-=(ModInt &a, ModInt b) {
    a = a - b;
    return a;
}

ModInt operator*(ModInt a, ModInt b) {
    return ModInt((uint64_t)a.v * (uint64_t)b.v % MOD);
}

ModInt& operator*=(ModInt &a, ModInt b) {
    a = a * b;
    return a;
}

ModInt pow(ModInt a, uint32_t n) {
    ModInt t(1);
    ModInt s = a;
    while (n > 0) {
        if (n & 1) t *= s;
        s *= s;
        n >>= 1;
    }
    return t;
}

ModInt operator/(ModInt a, Num b) {
    return a * pow(ModInt(b), MOD - 2);
}

ModInt operator/(ModInt a, ModInt b) {
    return a * pow(b, MOD - 2);
}

ModInt& operator/=(ModInt &a, ModInt b) {
    a = a / b;
    return a;
}

ModInt operator-(ModInt a) {
    if (a.v == 0) return ModInt(0);
    return ModInt(MOD - a.v);
}

struct Precalc {
    size_t n;
    vector<ModInt> inv;
    vector<ModInt> fact;
    vector<ModInt> ifact;

    Precalc(size_t n_) : n(n_), inv(n_ + 1, ModInt(1)), fact(n_ + 1, ModInt(1)), ifact(n_ + 1, ModInt(1)) {
        for (size_t i = 1; i <= n; i++) {
            if (i > 2) {
                inv[i] = -inv[MOD % i] * ModInt(MOD / (uint32_t)i);
            }
            fact[i] = ModInt((uint32_t)i) * fact[i - 1];
            ifact[i] = inv[i] * ifact[i - 1];
        }
    }

    ModInt fact_at(size_t x) const {
        return fact[x];
    }
    ModInt inv_at(size_t x) const {
        return inv[x];
    }
    ModInt ifact_at(size_t x) const {
        return ifact[x];
    }
    ModInt comb(size_t n_, size_t k) const {
        if (!(k <= n_)) {
            return ModInt(0);
        }
        return fact[n_] * ifact[k] * ifact[n_ - k];
    }
};

ostream& operator<<(ostream &os, const ModInt &m) {
    os << m.v;
    return os;
}

// ---------- end ModInt ----------

template <>
struct SemiRing<ModInt> {
    static ModInt one() { return ModInt(1); }
    static ModInt zero() { return ModInt(0); }
};

void run() {
    uint64_t n;
    size_t m;
    cin >> n >> m;
    using M = SquareMatrix<ModInt>;
    M t = M::identity(m);
    M s = M::zero(m);
    for (size_t i = 1; i < m; i++) {
        s.set_at(i - 1, i, ModInt(1));
    }
    s.set_at(m - 1, 0, ModInt(1));
    s.set_at(m - 1, m - 1, ModInt(1));
    uint64_t nn = n;
    while (nn > 0) {
        if ((nn & 1) == 1) {
            t = t * s;
        }
        s = s * s;
        nn >>= 1;
    }
    ModInt ans = t.get_at(m - 1, m - 1);
    cout << ans << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    run();
    return 0;
}

