#include <bits/stdc++.h>
using namespace std;

// ---------- begin Matrix ----------

template <class T>
struct SemiRing {
    static T zero();
    static T one();
};

template <class T>
struct SquareMatrix {
    size_t n;
    std::vector<T> a;

    SquareMatrix() : n(0) {}
    SquareMatrix(size_t n_) : n(n_), a(n_ * n_) {}

    static SquareMatrix zero(size_t n) {
        SquareMatrix m(n);
        T z = SemiRing<T>::zero();
        std::fill(m.a.begin(), m.a.end(), z);
        return m;
    }

    static SquareMatrix identity(size_t n) {
        SquareMatrix m = zero(n);
        for (size_t i = 0; i < n; i++) {
            m.a[i * n + i] = SemiRing<T>::one();
        }
        return m;
    }

    void set_at(size_t i, size_t j, T v) {
        assert(i < n && j < n);
        a[i * n + j] = v;
    }

    T get_at(size_t i, size_t j) const {
        assert(i < n && j < n);
        return a[i * n + j];
    }

    static SquareMatrix matmul(const SquareMatrix &l, const SquareMatrix &r) {
        return l * r;
    }

    SquareMatrix operator+(const SquareMatrix &rhs) const {
        assert(n == rhs.n);
        SquareMatrix c = zero(n);
        for (size_t i = 0; i < n * n; i++) {
            c.a[i] = a[i] + rhs.a[i];
        }
        return c;
    }

    SquareMatrix operator*(const SquareMatrix &rhs) const {
        assert(n == rhs.n);
        SquareMatrix c = zero(n);
        for (size_t i = 0; i < n; i++) {
            for (size_t k = 0; k < n; k++) {
                T aval = a[i * n + k];
                for (size_t j = 0; j < n; j++) {
                    c.a[i * n + j] = c.a[i * n + j] + aval * rhs.a[k * n + j];
                }
            }
        }
        return c;
    }
};

