// ---------- begin ModInt ----------

const uint32_t MOD = 1000000000 + 7;

template <class T>
struct ModInt {
    T v;
    ModInt() : v(0) {}
    ModInt(T _v) : v(_v) {}
};

using Num = uint32_t;

ModInt<Num> operator+(ModInt<Num> a, ModInt<Num> b) {
    uint32_t d = a.v + b.v;
    if (d >= MOD) d -= MOD;
    return ModInt<Num>(d);
}

ModInt<Num>& operator+=(ModInt<Num>& a, ModInt<Num> b) {
    a = a + b;
    return a;
}

ModInt<Num> operator-(ModInt<Num> a, ModInt<Num> b) {
    uint32_t d = a.v + MOD - b.v;
    if (d >= MOD) d -= MOD;
    return ModInt<Num>(d);
}

ModInt<Num>& operator-=(ModInt<Num>& a, ModInt<Num> b) {
    a = a - b;
    return a;
}

ModInt<Num> operator*(ModInt<Num> a, ModInt<Num> b) {
    uint64_t res = (uint64_t)a.v * (uint64_t)b.v % (uint64_t)MOD;
    return ModInt<Num>((uint32_t)res);
}

ModInt<Num>& operator*=(ModInt<Num>& a, ModInt<Num> b) {
    a = a * b;
    return a;
}

ModInt<Num> modint_pow(ModInt<Num> base, uint32_t n) {
    ModInt<Num> t(1);
    ModInt<Num> s = ModInt<Num>(base.v % MOD);
    while (n > 0) {
        if (n & 1) t *= s;
        s *= s;
        n >>= 1;
    }
    return t;
}

ModInt<Num> operator/(ModInt<Num> a, Num b) {
    return a * modint_pow(ModInt<Num>(b), MOD - 2);
}

ModInt<Num> operator/(ModInt<Num> a, ModInt<Num> b) {
    return a * modint_pow(b, MOD - 2);
}

ModInt<Num>& operator/=(ModInt<Num>& a, ModInt<Num> b) {
    a = a / b;
    return a;
}

ModInt<Num> operator-(ModInt<Num> a) {
    if (a.v == 0) return ModInt<Num>(0);
    return ModInt<Num>(MOD - a.v);
}

ModInt<Num> ModInt_new(uint32_t v) {
    return ModInt<Num>(v % MOD);
}

struct Precalc {
    size_t n;
    std::vector<ModInt<Num>> inv;
    std::vector<ModInt<Num>> fact;
    std::vector<ModInt<Num>> ifact;

    Precalc(size_t n_) : n(n_), inv(n_ + 1), fact(n_ + 1), ifact(n_ + 1) {
        inv[0] = ModInt<Num>(1);
        fact[0] = ModInt<Num>(1);
        ifact[0] = ModInt<Num>(1);
        for (size_t i = 1; i <= n; i++) {
            inv[i] = ModInt<Num>(1);
            fact[i] = ModInt<Num>(1);
            ifact[i] = ModInt<Num>(1);
        }
        for (size_t i = 1; i <= n; i++) {
            if (i > 2) {
                inv[i] = -inv[MOD % (uint32_t)i] * ModInt<Num>(MOD / (uint32_t)i);
            }
            fact[i] = ModInt<Num>((uint32_t)i) * fact[i - 1];
            ifact[i] = inv[i] * ifact[i - 1];
        }
    }

    ModInt<Num> fact_at(size_t x) const {
        return fact[x];
    }
    ModInt<Num> inv_at(size_t x) const {
        return inv[x];
    }
    ModInt<Num> ifact_at(size_t x) const {
        return ifact[x];
    }
    ModInt<Num> comb(size_t nn, size_t k) const {
        if (!(k <= nn)) return ModInt<Num>(0);
        return fact[nn] * ifact[k] * ifact[nn - k];
    }
};

std::ostream& operator<<(std::ostream& os, const ModInt<Num>& m) {
    os << m.v;
    return os;
}

// ---------- end ModInt ----------

template <>
struct SemiRing<ModInt<Num>> {
    static ModInt<Num> one() { return ModInt<Num>(1); }
    static ModInt<Num> zero() { return ModInt<Num>(0); }
};

void run() {
    uint64_t n;
    size_t m;
    cin >> n >> m;
    using M = SquareMatrix<ModInt<Num>>;
    M t = M::identity(m);
    M s = M::zero(m);
    for (size_t i = 1; i < m; i++) {
        s.set_at(i - 1, i, ModInt<Num>(1));
    }
    s.set_at(m - 1, 0, ModInt<Num>(1));
    s.set_at(m - 1, m - 1, ModInt<Num>(1));
    uint64_t nn = n;
    while (nn > 0) {
        if ((nn & 1) == 1) {
            t = t * s;
        }
        s = s * s;
        nn >>= 1;
    }
    ModInt<Num> ans = t.get_at(m - 1, m - 1);
    cout << ans << '\n';
}

